#wemd .wemd-steps[data-variant="steps-creator-default"] {
  counter-reset: step;
  padding: 0;
  list-style: none;
}
#wemd .wemd-steps[data-variant="steps-creator-default"] .wemd-step {
  counter-increment: step;
  padding: 0.75em 0 0.75em 2.5em;
  position: relative;
  border-left: 2px solid #3B82F6;
  margin-left: 1em;
}
#wemd .wemd-steps[data-variant="steps-creator-default"] .wemd-step::before {
  content: counter(step);
  position: absolute;
  left: -1em;
  top: 0.75em;
  width: 2em;
  height: 2em;
  background: #3B82F6;
  color: #fff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.85em;
  font-weight: 600;
}

